const d = $json.body || $json;
const now = new Date();
const pad = n => String(n).padStart(2,'0');
const ts = [
  now.getFullYear(),
  pad(now.getMonth()+1),
  pad(now.getDate()),
  pad(now.getHours()),
  pad(now.getMinutes()),
  pad(now.getSeconds())
].join('');

const id = `CMP-${ts}`;

const tanggalSubmit = now.toLocaleString('id-ID', {
  timeZone: 'Asia/Jakarta',
  day:'2-digit', month:'2-digit', year:'numeric',
  hour:'2-digit', minute:'2-digit', second:'2-digit'
});

const attachments = Array.isArray(d.attachments) ? d.attachments : [];

return [{
  json: {
    ID: id,
    Tanggal_Komplain: d.tanggal_komplain || now.toISOString().split('T')[0],
    Nama_Project: d.nama_project || '',
    Komplain: d.komplain || '',
    Pengaju: d.pengaju || '',
    Prioritas: d.prioritas || 'Sedang',
    Kategori: d.kategori || 'Lainnya',
    Status_Workflow: 'pending',
    Status_Pekerjaan: 'Proses',
    Status_Pekerjaan_Counter: 0,
    Tanggal_Submit: tanggalSubmit,
    _attachments: attachments,
    _hasAttachments: attachments.length > 0,
    PIC_Mandor: d.pic || '',                 // ← huruf besar P,I,C
    PIC_Pengawas: d.pic_pengawas || '', // ← tambahkan ini
    Lokasi: (d.lokasi || '').trim(),
    Tipe: d.tipe || ''
  }
}];

// ── Split: output 1 item per file, dengan binary data ────
const formData = $input.first().json;
const files    = formData._attachments || [];

return files.map((f, i) => ({
  json: {
    _formID:    formData.ID,
    _fileIndex: i,
    _fileName:  f.name,
    _fileMime:  f.type || 'application/octet-stream'
  },
  binary: {
    data: {   // ← ganti dari 'attachment' menjadi 'data'
      data:     f.data,
      mimeType: f.type || 'application/octet-stream',
      fileName: f.name,
      fileSize: f.size || 0
    }
  }
}));

// ── No attachment path: pass form data with empty attachment URL columns ──
const formData = $input.first().json;

return [{
  json: {
    ...formData,
    _attachments: undefined,
    _hasAttachments: undefined,
    URL_1: '-',
    URL_2: '-',
    URL_3: '-',
    URL_4: '-',
    URL_5: '-',
  }
}];

// Ambil semua item hasil dari node "Upload File ke Drive"
const items = $input.all();
const formData = $('Generate ID & Parse Data').first().json;

// Fungsi ambil link file Drive secara robust
function getDriveLink(fileJson) {
  // Beberapa versi node Drive n8n bisa mengembalikan field berbeda
  const direct =
    fileJson.webViewLink ||
    fileJson.alternateLink ||
    fileJson.url ||
    fileJson.link;

  if (direct) return direct;

  // Kalau tidak ada link, coba buat dari id
  if (fileJson.id) {
    return `https://drive.google.com/file/d/${fileJson.id}/view`;
  }

  // Fallback terakhir
  return '';
}

// Kumpulkan link dari semua attachment
const links = items
  .map(it => getDriveLink(it.json))
  .filter(l => l && String(l).trim() !== '');

// Maksimal 5 link, sisanya diabaikan
const five = links.slice(0, 5);

// Bentuk output ke 5 kolom URL_1..URL_5
const urlCols = {
  URL_1: five[0] || '-',
  URL_2: five[1] || '-',
  URL_3: five[2] || '-',
  URL_4: five[3] || '-',
  URL_5: five[4] || '-',
};

return [{
  json: {
    ...formData,
    _attachments: undefined,
    _hasAttachments: undefined,
    ...urlCols,
  }
}];

// Parse filter dari request body
const body = $json.body || $json;

// Ekstrak semua filter
const filters = {
  pic: (body.pic || '').trim(),
  nama_project: (body.nama_project || '').trim(),
  tipe: (body.tipe || '').trim(),
  status: (body.status || '').trim(),
  prioritas: (body.prioritas || '').trim(),
  id_tiket: (body.id_tiket || '').trim().toUpperCase(),
  pengaju: (body.pengaju || '').trim().toLowerCase(),
  tanggal_komplain: (body.tanggal_komplain || '').trim()
};

// Return untuk query ke sheet
return [{
  json: { filters }
}];

// Filter data berdasarkan kriteria yang dikirim dari frontend
const filters = $('Parse Filter').first().json.filters;
const allRows = $input.all();

const filtered = allRows.filter(item => {
  const row = item.json;

  // Filter PIC Pengawas (karena from webhook mengirim pic untuk PIC Pengawas)
  if (filters.pic && row.PIC_Pengawas !== filters.pic) return false;

  // Filter Nama Project
  if (filters.nama_project && row.Nama_Project !== filters.nama_project) return false;

  // Filter Tipe Laporan
  if (filters.tipe && row.Tipe_Laporan !== filters.tipe) return false;

  // Filter Status Pekerjaan
  if (filters.status) {
    const rowStatus = (row.Status_Pekerjaan || '').toLowerCase();
    const filterStatus = filters.status.toLowerCase();
    if (rowStatus !== filterStatus) return false;
  }

  // Filter Prioritas
  if (filters.prioritas && row.Prioritas !== filters.prioritas) return false;

  // Filter ID Tiket (partial match)
  if (filters.id_tiket) {
    const rowId = (row.ID || '').toUpperCase();
    if (!rowId.includes(filters.id_tiket)) return false;
  }

  // Filter Pengaju (partial match, case insensitive)
  if (filters.pengaju) {
    const rowPengaju = (row.Pengaju || '').toLowerCase();
    if (!rowPengaju.includes(filters.pengaju)) return false;
  }

  // Filter Tanggal
  if (filters.tanggal_komplain && row.Tanggal_Komplain !== filters.tanggal_komplain) return false;

  return true;
});

// Return hasil filter dengan pic diambil dari PIC_Pengawas (konsisten dengan filter)
return filtered.map(item => ({
  json: {
    id_tiket: item.json.ID,
    tanggal_komplain: item.json.Tanggal_Komplain,
    nama_project: item.json.Nama_Project,
    pic: item.json.PIC_Pengawas,      // <-- diperbaiki: ambil dari PIC_Pengawas
    komplain: item.json.Komplain,
    lokasi: item.json.Lokasi,
    tipe: item.json.Tipe_Laporan,
    pengaju: item.json.Pengaju,
    prioritas: item.json.Prioritas,
    kategori: item.json.Kategori,
    status: item.json.Status_Pekerjaan || 'Proses',
    update_notes: item.json.Update_Notes || '',
    tanggal_submit: item.json.Tanggal_Submit
  }
}));

// Parse data dari request
const body = $json.body || $json;

const id_tiket = (body.id_tiket || '').trim();
const status_pekerjaan = (body.status || 'Proses').trim();
const update_notes = (body.update_notes || '').trim();
const attachments = Array.isArray(body.attachments) ? body.attachments : [];

if (!id_tiket) {
  throw new Error('ID Tiket tidak boleh kosong');
}

// Buat timestamp untuk Tanggal_Update
const now = new Date();
const tanggalUpdate = now.toLocaleString('id-ID', {
  timeZone: 'Asia/Jakarta',
  day: '2-digit',
  month: '2-digit',
  year: 'numeric',
  hour: '2-digit',
  minute: '2-digit',
  second: '2-digit'
});

// Siapkan objek hasil
const result = {
  id_tiket,
  Status_Pekerjaan: status_pekerjaan,
  update_notes,
  _attachments: attachments,
  _hasAttachments: attachments.length > 0,
  Tanggal_Update: tanggalUpdate
};

// Hanya tambahkan field counter jika status = 'proses'
if (status_pekerjaan.toLowerCase() === 'proses') {
  result.Status_Pekerjaan_Counter = 0;
}

return [{ json: result }];

// Split attachment menjadi item terpisah untuk upload
const updateData = $input.first().json;
const files = updateData._attachments || [];

return files.map((f, i) => ({
  json: {
    _ticketID: updateData.id_tiket,
    _fileIndex: i,
    _fileName: f.name,
    _fileMime: f.type || 'application/octet-stream'
  },
  binary: {
    data: {
      data: f.data,
      mimeType: f.type || 'application/octet-stream',
      fileName: f.name,
      fileSize: f.size || 0
    }
  }
}));

// Kumpulkan semua link file yang sudah diupload
const items = $input.all();
const updateData = $('Parse Update Data').first().json;

// Ambil link dari hasil upload
const urls = items.map(item => {
  const webViewLink = item.json.webViewLink || '';
  return webViewLink;
}).filter(Boolean);

// Buat object dengan max 5 URL
const result = {
  ...updateData,
  _attachments: undefined,
  _hasAttachments: undefined,
  Up_1: urls[0] || '-',
  Up_2: urls[1] || '-',
  Up_3: urls[2] || '-',
  Up_4: urls[3] || '-',
  Up_5: urls[4] || '-'
};

return [{ json: result }];

// Tidak ada attachment - set semua URL ke dash
const updateData = $input.first().json;

return [{
  json: {
    ...updateData,
    _attachments: undefined,
    _hasAttachments: undefined,
    Up_1: '-',
    Up_2: '-',
    Up_3: '-',
    Up_4: '-',
    Up_5: '-'
  }
}];

// Tambahkan ID ke mapping
const data = $input.first().json;
return [{
  json: {
    ...data,
    ID: data.id_tiket
  }
}];

